import {readFile,writeFile} from 'node:fs/promises';import {resolve} from 'node:path';import {createRequire} from 'node:module';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const r=resolve('.local/step07-review/independent-round13'),root=process.cwd(),runtime=process.cwd(),require=createRequire(resolve('apps/api/package.json')),{PrismaClient}=require('@prisma/client');
const partial=process.argv.includes('--production-only')?'partial-production-':'';const own=JSON.parse(await readFile('.local/postgres/ownership.json','utf8'));assert.equal(own.port,55505);const lines=await readFile('.env','utf8').catch(e=>{if(e.code==='ENOENT')return readFile(r+'/private/env-held','utf8');throw e}),dsn=lines.split('\n').find(x=>x.startsWith('DATABASE_URL=')).slice(13),sha=x=>createHash('sha256').update(x).digest('hex'),rows=[];
for(const [mode,label] of [['production','production'],['dev','dev']]){if(partial&&mode!=='production')continue;
 const base=runtime+'/.local/step07/browser/'+mode;let e;try{e=JSON.parse(await readFile(base+'/evidence.json','utf8'))}catch(err){if(err.code==='ENOENT')continue;throw err}
 const o=JSON.parse(await readFile(r+'/private/'+label+'-fixture.json','utf8')),u=new URL(dsn);u.pathname='/'+o.database;const db=new PrismaClient({datasources:{db:{url:u.href}}});
 try{const actual=await db.$queryRawUnsafe("SELECT current_setting('data_directory') AS dir");assert.equal(resolve(actual[0].dir),resolve('.local/postgres/data'));
  const project=await db.project.findUniqueOrThrow({where:{id:e.projectId}});assert.equal(project.successfulBuildId,e.retired);
  for(const [position,id] of [['first',e.first],['second',e.second]]){const build=await db.build.findUniqueOrThrow({where:{id}}),f=await db.finalExport.findUniqueOrThrow({where:{buildId:id}}),snapshot=await db.projectSnapshot.findUniqueOrThrow({where:{id:build.projectSnapshotId}}),jobs=await db.studioJob.findMany({where:{buildId:id}});assert.equal(build.projectId,e.projectId);assert.equal(snapshot.projectId,e.projectId);assert(jobs.length&&jobs.every(x=>x.projectId===e.projectId&&x.state==='COMPLETED'));assert.equal(f.profileHash,'48844001eea07a8cf0da4baf9abb1653b01c38a9405413ed3123df189cf48793');
   const members=[];assert.equal(Object.keys(f.files).length,8);const checks=JSON.parse(await readFile(r+'/evidence/'+partial+'latest-browser-archive-verification.json','utf8')).downloads.find(x=>x.mode===mode&&x.downloadPosition===position);assert(checks);assert.equal(f.manifestSha,checks.artifact.manifestSHA256);const names=Object.keys(f.files);
   for(const name of names){const ref=f.files[name],file=await db.fileObject.findUniqueOrThrow({where:{sha256:ref.sha256}});assert.equal(file.key,ref.key);assert.equal(file.bytes,ref.bytes);assert.match(file.key,/^objects\/[a-f0-9]{64}$/);const bytes=await readFile(resolve(runtime,o.assetRoot,file.key)),dirbytes=await readFile(resolve(runtime,o.assetRoot,'builds',f.exportId,name));assert(bytes.equals(dirbytes));assert.equal(sha(bytes),file.sha256);assert.equal(bytes.length,file.bytes);assert.equal(sha(bytes),checks.artifact.members[name].sha256);if(name==='manifest.json'){const m=JSON.parse(bytes);assert.equal(m.buildId,checks.artifact.exportBuildId);assert.equal(m.identity.context.commit,'1be820a5adfbb3c41c532fbc778958774ed1c470')}members.push({name,bytes:bytes.length,sha256:sha(bytes),objectDirectoryAndWireIdentical:true})}
   const internal=await db.buildFile.findMany({where:{buildId:id}});assert.equal(internal.length,4);rows.push({mode,downloadPosition:position,projectId:e.projectId,buildId:id,projectCurrent:e.retired,projectSnapshotId:snapshot.id,snapshotRevision:snapshot.revision,publication:build.publication,manifestSHA256:f.manifestSha,standardExportBuildIdentity:checks.artifact.exportBuildId,standardFiles:members,standardCount:8,internalCount:4,completedJobs:jobs.map(x=>x.id),readOnly:true});
  }
 }finally{await db.$disconnect()}
}
await writeFile(r+'/evidence/'+partial+'current-db-export-file-links.json',JSON.stringify({source:'1be820a5adfbb3c41c532fbc778958774ed1c470',selectedDBBuilds:rows.length,rows,scope:'Only own synthetic new PG55505 databases read; no reset/drop/republication or new HTTP processing; standard8 and internal4 kept distinct'},null,2)+'\n');console.log(JSON.stringify({DBBuilds:rows.length,objectsDirectoriesAndWireIdentical:true}));
